-- =====================================================================================
-- PIPING v8.16 · Accesorios de tubería, bridas y tuberías de acero en tablas separadas
--   piping_acc_modelos     tipos de accesorio, de brida y de tubería de acero que se eligen al insertar (Codo 90° LR · ASME B16.9, Brida WN · ASME B16.5, Tubería de acero ASME ...)
--   piping_acc_medidas     medidas nominales: NPS / DN y diámetro exterior (ASME y EN)
--   piping_acc_espesores   espesor por medida y schedule / serie
--   piping_acc_materiales  grados de material, con código corto, familia y equivalencia
--   piping_acc_ratings     rating (clases ASME) y PN (EN)
--   piping_acc_cotas       cotas de norma por modelo y medida (consulta)
-- El accesorio concreto (modelo + medida + schedule + material + rating) no se guarda aquí: se compone en el plano
-- y su código es TIPO-MEDIDA-SCHEDULE-MATERIAL(-RATING), p. ej. C90LR-2"-S40-WPB.
--
-- Ejecutar en Supabase > SQL Editor después de 05 y 06. Trae los datos: no hay que importar ningún CSV.
-- Se puede repetir: no pisa lo que se haya editado ni recupera lo eliminado.
-- Elimina la tabla piping_accesorios de las versiones 8.8 y 8.9 (catálogo de 650 / 9 748 filas), que deja de usarse.
-- Lectura: cualquiera con la clave anon (piping_acc_tablas). Cambios en los modelos desde la aplicación: solo administrador.
-- Las demás tablas se editan en Supabase > Table Editor; la aplicación las vuelve a leer al abrirse.
-- =====================================================================================

drop function if exists public.piping_accesorios_listar();
drop function if exists public.piping_accesorios_listar(text, text, text, integer);
drop function if exists public.piping_accesorios_cambios();
drop function if exists public.piping_accesorio_guardar(text, json);
drop function if exists public.piping_accesorio_borrar(text, text);
drop function if exists public.piping_accesorios_recuperar(text);
drop table if exists public.piping_accesorios cascade;
drop function if exists public.piping_accesorios_marcar();

create table if not exists public.piping_acc_modelos (
    id              text primary key,                 -- NORMA-CÓDIGO, p. ej. B169-C90LR
    cod             text not null,                    -- código del tipo que va en la etiqueta: C90LR, TE, RC...
    subtipo         text not null,                    -- símbolo de la aplicación: codo45, codo60, codo90, tee, cruce, reduccion
    tipo            text default '',
    variante        text default '',
    nombre          text not null,
    sistema         text not null default 'ASME' check (sistema in ('ASME', 'EN')),   -- ASME: pulgadas · EN: DN
    norma           text default '',
    conexion        text default '',
    tipo_crane      text default '',                  -- tipo de pérdida de carga (Crane TP-410)
    mat_grupo       text default '',                  -- grupo de materiales que admite (piping_acc_materiales.grupo)
    esp_tabla       text default 'ASME',              -- ASME (B36.10 / B36.19 según el material), EN1 o EN2
    k               numeric,                          -- K del fabricante (vacío = Crane)
    notas           text default '',
    orden           integer not null default 100000,
    origen          text not null default 'empresa',  -- 'catálogo' (normas) o 'empresa'
    fabricante      text default '',
    referencia      text default '',
    url             text default '',
    activo          boolean not null default true,
    modificado      timestamptz,
    modificado_por  text
);
create table if not exists public.piping_acc_medidas (
    sistema  text not null check (sistema in ('ASME', 'EN')),
    dn       integer not null,
    nps      text default '',
    od       numeric not null,
    primary key (sistema, dn)
);
create table if not exists public.piping_acc_espesores (
    tabla     text not null,           -- B36.10, B36.19, EN1, EN2
    familia   text not null default 'Acero al carbono',
    dn        integer not null,
    schedule  text not null,           -- Sch 40, STD, Sch 10S, Serie 3, 2.9 mm...
    espesor   numeric not null,
    primary key (tabla, dn, schedule)
);
create table if not exists public.piping_acc_materiales (
    codigo       text not null,        -- código corto para el código del accesorio o del tubo: WPB, WP316L, A106B...
    designacion  text primary key,     -- SA-234 Gr.WPB
    familia      text not null check (familia in ('Acero al carbono', 'Acero inoxidable')),
    grupo        text not null,        -- BW-ASME, FORJ-ASME, EN1, EN2
    norma        text default '',
    equivalente  text default '',
    orden        integer not null default 1000
);
create table if not exists public.piping_acc_ratings (
    rating   text primary key,         -- 150#, 300#, PN 16...
    sistema  text not null check (sistema in ('ASME', 'EN')),
    notas    text default '',
    orden    integer not null default 1000
);
create table if not exists public.piping_acc_cotas (
    modelo  text not null,
    dn      integer not null,
    dn2     integer not null default 0,   -- 0 = sin extremo menor
    rating  text not null default '',
    cotas   text default '',
    theta   numeric,
    primary key (modelo, dn, dn2, rating)
);
-- v8.13 (bridas): cada modelo puede limitar sus rating / PN, sus tipos de cara y su rango de medidas
alter table public.piping_acc_modelos add column if not exists ratings text default '';   -- lista separada por comas (vacío = todos los de su sistema)
alter table public.piping_acc_modelos add column if not exists caras   text default '';   -- tipos de cara: RF,FF,RTJ · A,B1,B2...
alter table public.piping_acc_modelos add column if not exists dn_min  integer;
alter table public.piping_acc_modelos add column if not exists dn_max  integer;
-- v8.11: la clave de materiales pasa a ser la designación (un mismo código corto puede servir a tubo y a accesorio)
do $$ begin
    if exists (select 1 from pg_index i join pg_attribute a on a.attrelid = i.indrelid and a.attnum = any(i.indkey) where i.indrelid = 'public.piping_acc_materiales'::regclass and i.indisprimary and a.attname = 'codigo') then
        alter table public.piping_acc_materiales drop constraint piping_acc_materiales_pkey;
        alter table public.piping_acc_materiales add primary key (designacion);
    end if;
end $$;
alter table public.piping_acc_modelos enable row level security;
alter table public.piping_acc_medidas enable row level security;
alter table public.piping_acc_espesores enable row level security;
alter table public.piping_acc_materiales enable row level security;
alter table public.piping_acc_ratings enable row level security;
alter table public.piping_acc_cotas enable row level security;
revoke all on public.piping_acc_modelos, public.piping_acc_medidas, public.piping_acc_espesores, public.piping_acc_materiales, public.piping_acc_ratings, public.piping_acc_cotas from anon, authenticated;

-- todas las tablas de una vez, para la aplicación
create or replace function public.piping_acc_tablas() returns json
language sql stable security definer set search_path = public as $$
    select json_build_object(
        'modelos',    coalesce((select json_agg(row_to_json(m) order by m.orden, m.id) from public.piping_acc_modelos m where m.activo), '[]'::json),
        'medidas',    coalesce((select json_agg(row_to_json(m) order by m.sistema, m.dn) from public.piping_acc_medidas m), '[]'::json),
        'espesores',  coalesce((select json_agg(row_to_json(e) order by e.tabla, e.dn, e.espesor) from public.piping_acc_espesores e), '[]'::json),
        'materiales', coalesce((select json_agg(row_to_json(x) order by x.orden, x.codigo) from public.piping_acc_materiales x), '[]'::json),
        'ratings',    coalesce((select json_agg(row_to_json(r) order by r.orden, r.rating) from public.piping_acc_ratings r), '[]'::json),
        'cotas',      coalesce((select json_agg(json_build_object('modelo', c.modelo, 'dn', c.dn, 'dn2', nullif(c.dn2, 0), 'rating', c.rating, 'cotas', c.cotas, 'theta', c.theta) order by c.modelo, c.dn, c.dn2 desc) from public.piping_acc_cotas c), '[]'::json)) $$;

create or replace function public.piping_acc_modelo_guardar(p_token text, p_item json) returns json
language plpgsql volatile security definer set search_path = public, extensions as $$
declare u public.piping_usuarios; a public.piping_acc_modelos; v_id text := nullif(trim(p_item->>'id'), ''); v_nuevo boolean;
begin
    u := public.piping_exigir_admin(p_token);
    if coalesce(trim(p_item->>'nombre'), '') = '' then raise exception 'Indica el nombre del modelo'; end if;
    if coalesce(trim(p_item->>'cod'), '') = '' then raise exception 'Indica el código del tipo (p. ej. C90LR)'; end if;
    if coalesce(trim(p_item->>'subtipo'), '') = '' then raise exception 'Indica el tipo de accesorio'; end if;
    if v_id is null then v_id := 'EMP-' || upper(trim(p_item->>'cod')); end if;
    if exists (select 1 from public.piping_acc_modelos where id = v_id and not activo) and coalesce(p_item->>'_nuevo', '') = 'si' then v_id := v_id || '-' || upper(encode(gen_random_bytes(2), 'hex')); end if;
    v_nuevo := not exists (select 1 from public.piping_acc_modelos where id = v_id);
    values (v_id, upper(trim(p_item->>'cod')), p_item->>'subtipo', coalesce(p_item->>'tipo', ''), coalesce(p_item->>'variante', ''), trim(p_item->>'nombre'), coalesce(nullif(p_item->>'sistema', ''), 'ASME'), coalesce(p_item->>'norma', ''),
            coalesce(p_item->>'conexion', ''), coalesce(p_item->>'tipo_crane', ''), coalesce(p_item->>'mat_grupo', ''), coalesce(nullif(p_item->>'esp_tabla', ''), 'ASME'), nullif(p_item->>'k', '')::numeric, coalesce(p_item->>'notas', ''),
            coalesce(nullif(p_item->>'orden', '')::integer, 100000), 'empresa', coalesce(p_item->>'fabricante', ''), coalesce(p_item->>'referencia', ''), coalesce(p_item->>'url', ''), true, now(), u.usuario,
            coalesce(p_item->>'ratings', ''), coalesce(p_item->>'caras', ''), nullif(p_item->>'dn_min', '')::integer, nullif(p_item->>'dn_max', '')::integer)
    on conflict (id) do update set cod = excluded.cod, subtipo = excluded.subtipo, tipo = excluded.tipo, variante = excluded.variante, nombre = excluded.nombre, sistema = excluded.sistema, norma = excluded.norma,
            conexion = excluded.conexion, tipo_crane = excluded.tipo_crane, mat_grupo = excluded.mat_grupo, esp_tabla = excluded.esp_tabla, k = excluded.k, notas = excluded.notas,
            fabricante = excluded.fabricante, referencia = excluded.referencia, url = excluded.url, ratings = excluded.ratings, caras = excluded.caras, dn_min = excluded.dn_min, dn_max = excluded.dn_max, activo = true, modificado = now(), modificado_por = u.usuario
    returning * into a;
    return row_to_json(a);
end $$;

create or replace function public.piping_acc_modelo_borrar(p_token text, p_id text) returns void
language plpgsql volatile security definer set search_path = public, extensions as $$
declare u public.piping_usuarios; n text;
begin
    u := public.piping_exigir_admin(p_token);
    update public.piping_acc_modelos set activo = false, modificado = now(), modificado_por = u.usuario where id = p_id returning nombre into n;
    if not found then raise exception 'Modelo no encontrado'; end if;
end $$;

create or replace function public.piping_acc_modelos_recuperar(p_token text) returns integer
language plpgsql volatile security definer set search_path = public, extensions as $$
declare n integer;
begin
    perform public.piping_exigir_admin(p_token);
    update public.piping_acc_modelos set activo = true where not activo; get diagnostics n = row_count; return n;
end $$;

grant execute on function public.piping_acc_tablas(), public.piping_acc_modelo_guardar(text, json), public.piping_acc_modelo_borrar(text, text), public.piping_acc_modelos_recuperar(text) to anon, authenticated;

